/// The single multiplexed event stream (ARCH §12.6).
/// Returns a broadcast [Stream] of events from the `engineEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<EngineEventMsg> engineEvents( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel engineEventsChannel =
      EventChannel('dev.flutter.pigeon.danaview_editor_engine.EngineEventsApi.engineEvents$instanceName', pigeonMethodCodec);
  return engineEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as EngineEventMsg;
  });
}
    
